export type Language = 'ar' | 'en';

export type Localized = {
  ar: string;
  en: string;
};

export type Pin = {
  id: number;
  label: Localized;
  detail: Localized;
  target: 'sender' | 'subject' | 'body' | 'link' | 'attachment' | 'footer';
};

export type EmailData = {
  id: string;
  senderName: Localized;
  senderAddress: string;
  subject: Localized;
  date: string;
  body: Localized;
  cta?: Localized;
  links?: { text: string; url: string }[];
  attachment?: string;
  footer?: Localized;
};

export type LearnCase = EmailData & {
  caseNumber: string;
  title: Localized;
  isPhishing: boolean;
  flags: Localized[];
  lesson: Localized;
  pins: Pin[];
};

export type QuizQuestion = EmailData & {
  isPhishing: boolean;
  explanation: Localized;
  flags: Localized[];
  lesson: Localized;
  category: string;
};

export const b = (ar: string, en: string): Localized => ({ ar, en });

